#!/bin/sh

CERT_DIR="/etc/letsencrypt"
NGINX_CONTAINER="${NGINX_CONTAINER:?NGINX_CONTAINER environment variable is required}"

echo "Watching $CERT_DIR for certificate changes..."

inotifywait -m -r -e close_write,moved_to,modify "$CERT_DIR" |
while read -r path event file; do
    case "$file" in
        *.pem|*.crt|*.key)
            echo "$(date): certificate change detected: $path$file"
            sleep 5

            # Drain additional events generated by the same certificate update.
            while read -t 0.1 -r _; do :; done

            echo "$(date): reloading nginx..."
            if docker exec "$NGINX_CONTAINER" nginx -s reload; then
                echo "$(date): nginx reloaded successfully"
            else
                echo "$(date): ERROR: nginx reload failed" >&2
            fi
            ;;
    esac
done
